import boto3

def check_unsafe_content(text):
    comprehend = boto3.client('comprehend')
    response = comprehend.detect_sentiment(Text=text, LanguageCode='en')
    sentiment = response['Sentiment']
    if sentiment == 'NEGATIVE':
        return True
    else:
        return False

if __name__ == '__main__':
    prompt = 'This is a sample prompt.'
    generated_text = 'This is a sample generated text.'
    if check_unsafe_content(prompt) or check_unsafe_content(generated_text):
        print('Unsafe content detected!')
    else:
        print('No unsafe content detected.')

from typing import Any, Dict, List, Union


class HostedLLMRequest:
    def __init__(self, model_id: str, prompt: str, max_tokens: int):
        self.model_id = model_id
        self.prompt = prompt
        self.max_tokens = max_tokens


class HostedLLMResponse:
    def __init__(self, generated_text: str):
        self.generated_text = generated_text


def normalize_hosted_llm_response(response: HostedLLMResponse) -> str:
    return response.generated_text.strip()


class ModelFamilySelectionRequest:
    def __init__(self, model_family: str, criteria: Dict[str, Any]):
        self.model_family = model_family
        self.criteria = criteria


class ModelFamilySelectionResponse:
    def __init__(self, selected_model: str):
        self.selected_model = selected_model


def normalize_model_family_selection_response(response: ModelFamilySelectionResponse) -> str:
    return response.selected_model.strip()

import boto3

BEDROCK_REGION = 'us-east-1'

def get_bedrock_client():
    return boto3.client('bedrock', region_name=BEDROCK_REGION)

def list_foundation_models():
    client = get_bedrock_client()
    response = client.list_foundation_models()
    return response['modelSummaries']

def get_model_details(model_id):
    client = get_bedrock_client()
    response = client.get_foundation_model(modelId=model_id)
    return response['modelDetails']

def invoke_model(model_id, payload):
    client = get_bedrock_client()
    response = client.invoke_model(
        modelId=model_id,
        body=payload
    )
    return response['output']

import boto3

def answer_with_context(question, context):
    bedrock = boto3.client('bedrock-runtime')
    response = bedrock.invoke_model(
        model_id='amazon.bedrock.model',
        body={
            'prompt': f'{context} {question}',
            'max_tokens': 150
        }
    )
    answer = response['output']['text']
    return answer

